content.text:
Each repeat instruction stores the request to copy in `req`. I will classify every start-arm repeat answer in passes 6, 8, 9 and 10:
- pass (checker);
- no answer;
- prefix: the exact request appears, but after something;
- corrupted: the opening of the answer closely matches the request but not exactly;
- none.

For the failures I will show where the copy diverges.

```python
# Hypothesis (cont.): classify start repeat answers: pass / no_answer / prefix / corrupted / none; show divergence points.
cls=[]; exs=collections.defaultdict(list)
for lab,M,G in SETS:
    for i,m in enumerate(M):
        if m.get('kind','if')!='if' or 'insts' not in m: continue
        for ins in m['insts']:
            if ins['type']!='repeat' or not ins.get('req'): continue
            kid=f'prompt/{i}'
            if kid not in G: continue
            t=G[kid]['text']
            if '</think>' not in t: c='no_answer'
            else:
                a=ans_of(t).strip(); req=ins['req'].strip()
                if check(ins, ans_of(t)): c='pass'
                else:
                    j=a.lower().find(req.lower())
                    if j>0: c='prefix'; exs[c].append(repr(a[:min(j,60)]))
                    else:
                        head=a[:len(req)]
                        sm=difflib.SequenceMatcher(None,head.lower(),req.lower())
                        r_=sm.ratio()
                        if r_>0.8:
                            c='corrupt'; mb=sm.get_matching_blocks()[0]
                            k_=0
                            while k_<min(len(head),len(req)) and head[k_].lower()==req[k_].lower(): k_+=1
                            exs[c].append(f"@{k_}/{len(req)} want {req[max(0,k_-12):k_+12]!r} got {head[max(0,k_-12):k_+12]!r}")
                        else: c='none'; exs[c].append(repr(a[:70]))
            cls.append((lab,c))
Cl=pd.DataFrame(cls,columns=['set','c']); print(Cl.groupby(['set','c']).size().unstack(fill_value=0))
for c in ['prefix','corrupt','none']:
    print('--',c); 
    for e in exs[c][:8]: print('  ',e[:150])
```

