Pass 15 is in. I will compute the same paired statistics for S=10 (pass 14) and S=15 (pass 15), each against start (pass 13), on identical tokens:
- comma effect on comma-ban answers: Δ log-prob at emitted commas, P(comma) at comma-risk positions, and the log-odds change at full firing;
- side effects: mean |Δ| on non-comma answer tokens, thinking tokens, commas in other answers, and keyword tokens.

```python
# Hypothesis: S=15 gives ~1.5x the comma effect of S=10 with side effects still ~0.01-0.03 nats (dose-response).
def dose(fdir):
    Lx=np.load(fdir+'/token_logprobs.npy'); Ki=np.load(fdir+'/topk_ids.npy',mmap_mode='r'); Kl=np.load(fdir+'/topk_logprobs.npy',mmap_mode='r')
    acc=collections.defaultdict(list); rk=[]; kw_=[]
    for i,mt in enumerate(meta13):
        tt=T13[i]; L=int((tt>=0).sum()); pe=np.where(tt[:L]==ET)[0]
        if len(pe)==0: continue
        a0_=pe[-1]+1; g_='NC' if mt['grp'] in ('NCc','NC0') else 'OTH'
        d=Lx[i]-L13[i]; ap=np.arange(a0_+1,L); iscm=(tt[ap]==CM)
        acc[('think',g_)].append(d[1:pe[-1]]); acc[('noncomma',g_)].append(d[ap][~iscm]); acc[('comma',g_)].append(d[ap][iscm])
        if g_=='NC':
            pos=np.arange(a0_,L-1)
            p13=np.where(K13i[i,pos]==CM,np.exp(K13l[i,pos].astype(np.float32)),0).sum(1)
            px=np.where(Ki[i,pos]==CM,np.exp(Kl[i,pos].astype(np.float32)),0).sum(1)
            for j in np.where(p13>.02)[0]: rk.append((p13[j],px[j]))
        if 'keyword' in mt['types']:
            M={'C1':C1m,'C2':C2m,'C3':C3}[mt['set']]; kws=[x['kw'].lower() for x in M[mt['i']]['insts'] if x['type']=='keyword']
            for t_ in ap:
                s_tok=tok.decode([int(tt[t_])]).lower().strip()
                if len(s_tok)>=3 and any(k in s_tok or k.startswith(s_tok) for k in kws): kw_.append(d[t_])
    out={}
    for k_,v in acc.items():
        v=np.concatenate(v); v=v[np.isfinite(v)]; out[k_]=(v.mean(),np.abs(v).mean(),np.mean(np.abs(v)>.5))
    rk=np.array(rk); out['risk']=(np.median(rk[:,1]), np.mean(rk[:,1]<.01), np.mean(rk[:,1]<.001))
    out['kw']=(np.mean(kw_), np.mean(np.abs(kw_)), len(kw_))
    return out
D14=dose('/work/fwd_14'); D15=dose('/work/fwd_15')
for k_ in [('comma','NC'),('noncomma','NC'),('comma','OTH'),('noncomma','OTH'),('think','NC'),('think','OTH'),'kw','risk']:
    print(str(k_).ljust(22), 'S10', np.round(D14[k_],4), ' S15', np.round(D15[k_],4))
```

